<?php\n// Inventory Management Functions\n\n/**\n * Add inventory from purchase invoice\n */\nfunction add_inventory_from_purchase($pdo, $invoice_id, $items) {\n    try {\n        foreach ($items as $item) {\n            if (!empty($item['chicken_type_id']) && !empty($item['quantity'])) {\n                // Check if inventory exists\n                $stmt = $pdo->prepare('SELECT inventory_id, quantity FROM inventory WHERE chicken_type_id = ? LIMIT 1');\n                $stmt->execute([$item['chicken_type_id']]);\n                $existing = $stmt->fetch();\n                \n                if ($existing) {\n                    // Update existing inventory\n                    $new_quantity = $existing['quantity'] + $item['quantity'];\n                    $stmt = $pdo->prepare('UPDATE inventory SET quantity = ? WHERE inventory_id = ?');\n                    $stmt->execute([$new_quantity, $existing['inventory_id']]);\n                    $inventory_id = $existing['inventory_id'];\n                } else {\n                    // Create new inventory entry\n                    $stmt = $pdo->prepare(\"\n                        INSERT INTO inventory (chicken_type_id, quantity, unit_price, warehouse_location, created_by)\n                        VALUES (?, ?, ?, ?, ?)\n                    \");\n                    $stmt->execute([\n                        $item['chicken_type_id'],\n                        $item['quantity'],\n                        $item['rate'],\n                        'Purchase: Invoice ' . $invoice_id,\n                        1\n                    ]);\n                    $inventory_id = $pdo->lastInsertId();\n                }\n                \n                // Log transaction\n                log_inventory_transaction($pdo, $inventory_id, $item['chicken_type_id'], $item['quantity'], 'purchase', $invoice_id, 'Added from purchase invoice');\n            }\n        }\n        return true;\n    } catch (Exception $e) {\n        throw new Exception('Error adding inventory: ' . $e->getMessage());\n    }\n}\n\n/**\n * Deduct inventory for sale invoice\n */\nfunction deduct_inventory_from_sale($pdo, $invoice_id, $items) {\n    try {\n        foreach ($items as $item) {\n            if (!empty($item['chicken_type_id']) && !empty($item['quantity'])) {\n                // Check if enough inventory exists\n                $stmt = $pdo->prepare('SELECT inventory_id, quantity FROM inventory WHERE chicken_type_id = ? LIMIT 1');\n                $stmt->execute([$item['chicken_type_id']]);\n                $inventory = $stmt->fetch();\n                \n                if (!$inventory) {\n                    throw new Exception('No inventory available for this chicken type');\n                }\n                \n                if ($inventory['quantity'] < $item['quantity']) {\n                    throw new Exception('Insufficient inventory. Available: ' . $inventory['quantity'] . ' kg');\n                }\n                \n                // Deduct inventory\n                $new_quantity = $inventory['quantity'] - $item['quantity'];\n                $stmt = $pdo->prepare('UPDATE inventory SET quantity = ? WHERE inventory_id = ?');\n                $stmt->execute([$new_quantity, $inventory['inventory_id']]);\n                \n                // Log transaction\n                log_inventory_transaction($pdo, $inventory['inventory_id'], $item['chicken_type_id'], $item['quantity'], 'sale', $invoice_id, 'Deducted from sale invoice');\n            }\n        }\n        return true;\n    } catch (Exception $e) {\n        throw new Exception($e->getMessage());\n    }\n}\n\n/**\n * Log inventory transaction\n */\nfunction log_inventory_transaction($pdo, $inventory_id, $chicken_type_id, $quantity, $type, $invoice_id, $notes = '') {\n    try {\n        $stmt = $pdo->prepare(\"\n            INSERT INTO inventory_transactions (inventory_id, chicken_type_id, quantity, transaction_type, invoice_id, notes, created_by)\n            VALUES (?, ?, ?, ?, ?, ?, ?)\n        \");\n        $stmt->execute([$inventory_id, $chicken_type_id, $quantity, $type, $invoice_id, $notes, 1]);\n    } catch (Exception $e) {\n        // Log error but don't fail the transaction\n        error_log('Error logging inventory transaction: ' . $e->getMessage());\n    }\n}\n\n/**\n * Get current inventory with valuation\n */\nfunction get_inventory_summary($pdo) {\n    $stmt = $pdo->query(\"\n        SELECT \n            i.inventory_id,\n            ct.name as chicken_name,\n            i.quantity,\n            i.unit_price,\n            (i.quantity * i.unit_price) as total_value,\n            i.warehouse_location,\n            i.updated_at\n        FROM inventory i\n        JOIN chicken_types ct ON i.chicken_type_id = ct.id\n        ORDER BY ct.name\n    \");\n    return $stmt->fetchAll();\n}\n\n/**\n * Get low stock items (less than 50 kg)\n */\nfunction get_low_stock_items($pdo, $threshold = 50) {\n    $stmt = $pdo->prepare(\"\n        SELECT \n            i.inventory_id,\n            ct.name as chicken_name,\n            i.quantity,\n            i.unit_price,\n            (i.quantity * i.unit_price) as total_value\n        FROM inventory i\n        JOIN chicken_types ct ON i.chicken_type_id = ct.id\n        WHERE i.quantity < ?\n        ORDER BY i.quantity ASC\n    \");\n    $stmt->execute([$threshold]);\n    return $stmt->fetchAll();\n}\n\n/**\n * Get total inventory value\n */\nfunction get_total_inventory_value($pdo) {\n    $stmt = $pdo->query(\"\n        SELECT SUM(quantity * unit_price) as total_value FROM inventory\n    \");\n    $result = $stmt->fetch();\n    return $result['total_value'] ?? 0;\n}\n\n/**\n * Get inventory by chicken type\n */\nfunction get_inventory_by_type($pdo, $chicken_type_id) {\n    $stmt = $pdo->prepare(\"\n        SELECT \n            i.inventory_id,\n            i.quantity,\n            i.unit_price,\n            (i.quantity * i.unit_price) as total_value,\n            i.warehouse_location\n        FROM inventory i\n        WHERE i.chicken_type_id = ?\n        LIMIT 1\n    \");\n    $stmt->execute([$chicken_type_id]);\n    return $stmt->fetch();\n}\n\n/**\n * Get inventory transaction history\n */\nfunction get_inventory_history($pdo, $limit = 50) {\n    $stmt = $pdo->query(\"\n        SELECT \n            it.transaction_id,\n            it.transaction_type,\n            ct.name as chicken_name,\n            it.quantity,\n            it.notes,\n            it.created_at,\n            i.invoice_number\n        FROM inventory_transactions it\n        JOIN chicken_types ct ON it.chicken_type_id = ct.id\n        LEFT JOIN invoices i ON it.invoice_id = i.invoice_id\n        ORDER BY it.created_at DESC\n        LIMIT $limit\n    \");\n    return $stmt->fetchAll();\n}\n\n/**\n * Check if inventory adjustment needed\n */\nfunction check_inventory_status($pdo) {\n    $low_stock = get_low_stock_items($pdo);\n    $total_value = get_total_inventory_value($pdo);\n    \n    return [\n        'low_stock_count' => count($low_stock),\n        'low_stock_items' => $low_stock,\n        'total_value' => $total_value\n    ];\n}\n?>\n